<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { newId, packageById, percent, save, state } from '../stores/lexigo'
const props = defineProps({ id: String }); const router = useRouter(); const pkg = computed(() => packageById(props.id)); const index = ref(0); const answer = ref(''); const score = ref(0); const checked = ref(false); const complete = computed(() => pkg.value && index.value >= pkg.value.words.length); const word = computed(() => pkg.value?.words[index.value]); const isCorrect = computed(() => answer.value.trim().toLowerCase() === word.value?.term.toLowerCase())
function check() { if (!answer.value.trim()) return; checked.value = true; if (isCorrect.value) score.value++ } function next() { index.value++; answer.value = ''; checked.value = false } function finish() { state.attempts.unshift({ id: newId('attempt'), packageId: pkg.value.id, score: score.value, total: pkg.value.words.length, at: Date.now() }); save(); router.push('/progress') }
</script>
<template><section v-if="pkg && !complete" class="mx-auto max-w-2xl px-5 py-10"><RouterLink :to="`/packages/${pkg.id}`" class="text-sm font-bold text-slate-500">← Leave practice</RouterLink><div class="mt-7 flex justify-between text-xs font-bold text-slate-500"><span>QUESTION {{ index + 1 }} OF {{ pkg.words.length }}</span><span class="text-lexi">{{ score }} correct</span></div><div class="mt-3 h-2 overflow-hidden rounded-full bg-slate-200"><i class="block h-full bg-emerald-500 transition-all" :style="{ width: `${percent(index, pkg.words.length)}%` }"></i></div><article class="mt-7 rounded-3xl border border-slate-200 bg-white p-9 text-center shadow-lg shadow-slate-200/60"><span class="text-4xl">💡</span><p class="mt-5 text-[11px] font-bold tracking-[.15em] text-lexi">WHAT IS THE ENGLISH WORD?</p><h1 class="mt-3 font-display text-4xl font-bold">{{ word.meaning || word.example || 'Listen and type the word' }}</h1><p v-if="word.example" class="mt-3 text-sm text-slate-500">Hint: {{ word.example }}</p><input v-model="answer" :disabled="checked" class="mt-7 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-center text-lg outline-lexi" placeholder="Type your answer" @keyup.enter="checked ? next() : check()"><p v-if="checked" class="mt-3 rounded-xl px-3 py-2 text-sm font-bold" :class="isCorrect ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-600'">{{ isCorrect ? 'Great job!' : `The answer is: ${word.term}` }}</p><button class="mt-3 w-full rounded-xl bg-lexi px-4 py-3 text-sm font-bold text-white" @click="checked ? next() : check()">{{ checked ? 'Next word →' : 'Check answer' }}</button></article></section><section v-else-if="pkg" class="mx-auto max-w-2xl px-5 py-20 text-center"><p class="text-6xl">🎉</p><p class="mt-5 text-[11px] font-bold tracking-[.15em] text-lexi">PRACTICE COMPLETE</p><h1 class="mt-2 font-display text-5xl font-bold">Well done!</h1><p class="mt-3 text-slate-500">You completed {{ pkg.name }}.</p><p class="mx-auto mt-7 grid h-36 w-36 place-items-center rounded-full border-10 border-violet-200 border-t-lexi font-display text-4xl font-bold text-lexi">{{ score }}<small class="-ml-12 mt-14 font-sans text-sm font-normal text-slate-400">/{{ pkg.words.length }}</small></p><button class="mt-7 rounded-xl bg-lexi px-4 py-3 text-sm font-bold text-white" @click="finish">View progress →</button></section></template>
